mapper.select:
SELECT a.id as id, a.report_id as reportId, a.appealer_id as appealerId, appealer.nickname as appealerNickname, appealer.face as appealerFace, a.appeal_type as appealType, a.target_id as targetId, CASE WHEN a.appeal_type = 1 THEN v.title ELSE NULL END as targetTitle, CASE WHEN a.appeal_type = 2 THEN c.content ELSE NULL END as targetContent, a.reason as reason, a.description as description, a.status as status, a.handler_id as handlerId, COALESCE(handler.real_name, handler.username) as handlerNickname, a.handle_time as handleTime, a.handle_result as handleResult, a.create_time as createTime, a.updated_time as updatedTime, a.is_deleted as isDeleted FROM `appeal` as a LEFT JOIN users as appealer ON a.appealer_id = appealer.id LEFT JOIN admin_users as handler ON a.handler_id = CAST(handler.id AS CHAR) LEFT JOIN report as r ON a.report_id = r.id LEFT JOIN vlog as v ON a.appeal_type = 1 AND a.target_id = v.id LEFT JOIN comment as c ON a.appeal_type = 2 AND a.target_id = c.id
AND a.appeal_type = #{paramMap.appealType}
AND a.status = #{paramMap.status}
AND a.target_id = #{paramMap.targetId}
AND a.report_id = #{paramMap.reportId}
AND a.appealer_id = #{paramMap.appealerId}
AND (a.is_deleted = 0 OR a.is_deleted IS NULL)
ORDER BY a.create_time DESC

SELECT id
FROM `appeal`
WHERE appealer_id = #{appealerId}
  AND report_id = #{reportId}
  AND (is_deleted = 0 OR is_deleted IS NULL)
LIMIT 1
